const snippets={"Python": ["", "", "class Solution:", "", "    def copyRandomList(self, head: 'Optional[Node]') -> 'Optional[Node]':", "        d = {}", "        dummy = tail = Node(0)", "        cur = head", "        while cur:", "            node = Node(cur.val)", "            tail.next = node", "            tail = tail.next", "            d[cur] = node", "            cur = cur.next", "        cur = head", "        while cur:", "            d[cur].random = d[cur.random] if cur.random else None", "            cur = cur.next", "        return dummy.next"], "Java": ["import java.util.*;", "class Solution {", "    public Node copyRandomList(Node head) {", "        Map<Node, Node> d = new HashMap<>();", "        Node dummy = new Node(0);", "        Node tail = dummy;", "        for (Node cur = head; cur != null; cur = cur.next) {", "            Node node = new Node(cur.val);", "            tail.next = node;", "            tail = node;", "            d.put(cur, node);", "        }", "        for (Node cur = head; cur != null; cur = cur.next) {", "            d.get(cur).random = cur.random == null ? null : d.get(cur.random);", "        }", "        return dummy.next;", "    }", "}"]};
